// ## src/middleware/validate.js
export const validate = (schemas) => (req, res, next) => {
  const errors = []
  req.validated = {}
  for (const part of ['params', 'query', 'body']) {
    if (!schemas[part]) continue
    const result = schemas[part].safeParse(req[part] ?? {})
    if (!result.success) {
      for (const issue of result.error.issues) {
        errors.push({ in: part, field: issue.path.join('.'), message: issue.message })
      }
    } else {
      req.validated[part] = result.data
    }
  }
  if (errors.length) return res.status(400).json({ status: 'fail', errors })
  next()
}

// ## src/routes/users.js
import { Router } from 'express'
import { z } from 'zod'
import { validate } from '../middleware/validate.js'

const createUser = z.object({
  name: z.string().trim().min(2).max(50),
  email: z.string().trim().toLowerCase().email(),
  age: z.coerce.number().int().min(13).max(120).optional(),
}).strict()                                           // unknown keys -> error

const listQuery = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(10),
})

const router = Router()

router.get('/', validate({ query: listQuery }), (req, res) => {
  res.json({ query: req.validated.query })
})

router.post('/', validate({ body: createUser }), (req, res) => {
  res.status(201).json(req.validated.body)
})

export default router

import { body, validationResult } from 'express-validator'

const rules = [
  body('email').trim().isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).withMessage('Min 8 characters'),
]

app.post('/register', rules, (req, res) => {
  const result = validationResult(req)
  if (!result.isEmpty()) return res.status(400).json({ errors: result.array() })
  res.status(201).json({ ok: true })
})

import express from 'express'
import cors from 'cors'

const app = express()

const allowed = (process.env.CORS_ORIGINS ?? 'http://localhost:5173').split(',')

app.use(cors({
  origin(origin, callback) {
    // no Origin header = curl / server-to-server / same-origin: allow
    if (!origin || allowed.includes(origin)) return callback(null, true)
    callback(new Error(`Origin ${origin} not allowed by CORS`))
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600,
}))

app.get('/api/ping', (req, res) => res.json({ pong: true }))
app.listen(3000)

